class LRUCache:
    def __init__(self, capacity):
        self.cache = {}
        self.capacity = capacity
        self.mru = []

    def put(self, key, value):
        if key not in self.cache:
            if len(self.cache) >= self.capacity:
                del self.cache[self.mru.pop(0)]
            self.mru.append(key)
        self.cache[key] = value

    def get(self, key):
        if key in self.cache:
            self.mru.remove(key)
            self.mru.append(key)
            return self.cache[key]
        else:
            return -1

def solve(data):
    cache = LRUCache(data['capacity'])
    for op, key, value in data['ops']:
        if op == 'put':
            cache.put(key, value)
        elif op == 'get':
            result = cache.get(key)
            return [result]
    return []

