def solve(data):
    capacity = data["capacity"]
    ops = data["ops"]

    if capacity == 0:
        return []

    cache = OrderedDict()
    recent_ops = []

    for op, key, value in ops:
        if op == "put":
            if len(cache) < capacity:
                cache[key] = value
                recent_ops.append((key, value))
            else:
                least_recent_key, _ = recent_ops.pop(0)
                del cache[least_recent_key]
                cache[key] = value
                recent_ops.append((key, value))
        elif op == "get":
            if key in cache:
                recent_ops.append((key, cache[key]))
                return [cache[key]]
            else:
                return [-1]

    return [cache[key] for key in cache.keys()]

