    cache = OrderedDict()

    def put(key, value):
        if key not in cache:
            if len(cache) == capacity:
                cache.popitem(last=False)
            cache[key] = value

    def get(key):
        if key in cache:
            cache.move_to_end(key, last=True)  # Update most recently used
            return cache[key]
        else:
            return -1

    results = []
    for op_type, key, value in ops:
        if op_type == "put":
            put(key, value)
        elif op_type == "get":
