class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.lru_keys = []

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        # Move the accessed key to the front of the LRU list
        self.lru_keys.remove(key)
        self.lru_keys.insert(0, key)
        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            # Update the value and move the key to the front of the LRU list
            self.cache[key] = value
            self.lru_keys.remove(key)
            self.lru_keys.insert(0, key)
        else:
            # If cache is full, remove the least recently used key
            if len(self.cache) == self.capacity:
                lru_key = self.lru_keys.pop()
                del self.cache[lru_key]
            # Add the new key-value pair to the cache
            self.cache[key] = value
            self.lru_keys.insert(0, key)

