def solve(data):
    capacity = data["capacity"]
    ops = data["ops"]

    if capacity == 0:
        return []

    cache = {}
    hit_count = {}
    latest_used = {}

    def update_cache(key, value):
        cache[key] = value
        hit_count[key] += 1
        latest_used[key] = len(ops)

    def get_key(key):
        if key not in cache:
            return None
        update_cache(key, cache[key])
        return key

    result = []
    for op, key, value in ops:
        if op == "put":
            update_cache(key, value)
        elif op == "get":
            result.append(get_key(key) or -1)
    return result

