class LRUCache:

    def __init__(self, capacity: int):
        self.cache = {}
        self.order = []

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1

        # Move the accessed item to the front of the order
        self.order.remove(key)
        self.order.append(key)

        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            # Update the value and move the item to the front of the order
            self.cache[key] = value
            self.order.remove(key)
            self.order.append(key)
        else:
            # Add the new item to the cache and order
            self.cache[key] = value
            if len(self.cache) > self.capacity:
                # Remove the least recently used item from the cache and order
                lru_key = self.order.pop(0)
                del self.cache[lru_key]

            # Append the new item to the end of the order
            self.order.append(key)


