    stack = []
    result = []

    for char in text:
        if char.isdigit():
            num = int(char)
            while stack and stack[-1].isdigit():
                num = num * 10 + int(stack.pop())
            stack.append(str(num))
        elif char == '[':
            stack.append(char)
        elif char == ']':
            temp = []
            while stack[-1] != '[':
                temp.insert(0, stack.pop())
            stack.pop()  # Remove the opening '['
            repeat_count = int(stack.pop())  # Get the repeat count
            repeated_text = ''.join(temp)
            result.extend([repeated_text] * repeat_count)
        else:
            result.append(char)

    return ''.join(result)

