def solve(data):
    # Parse the input JSON
    input_data = data['text']

    # Initialize the result list with the initial text
    result = [input_data]

    # Iterate through each character in the input text
    for char in input_data:
        if char.isdigit():
            # If the character is a digit, multiply the current result by the digit
            multiplier = int(char)
            result = [x * multiplier for x in result]
        elif char == '[':
            # If the character is '[', start a new recursion level
            sub_result = []
            depth = 1
            while depth > 0:
                char = next(result)
                if char == '[':
                    depth += 1
                elif char == ']':
                    depth -= 1
                else:
                    sub_result.append(char)
            # Recursively expand the sub-result
            expanded_sub_result = solve({'text': ''.join(sub_result)})
            # Add the expanded sub-result to the current result
            result = result[:-len(sub_result)] + expanded_sub_result
        else:
            # If the character is a letter, add it to the current result
            result.append(char)

    # Join the characters in the result list into a single string
    return ''.join(result)

