from collections import deque

class Solution(object):
    def solve(self, data):
        tokens = deque(data['tokens'])

        stack = []
        while tokens:
            token = tokens.popleft()
            if token.isdigit():
                stack.append(int(token))
            else:
                right = stack.pop()
                left = stack.pop()

                if token == '+':
                    stack.append(left + right)
                elif token == '-':
                    stack.append(left - right)
                elif token == '*':
                    stack.append(left * right)
                elif token == '/':
                    stack.append(int(left / right)) # Truncate towards zero

        return stack[0]

def solve(data):
    tokens = data['tokens']
    stack = []

    def calculate(a, b, op):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        else:
            # For division, use floor division to truncate towards zero
            return a // b

    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            stack.append(calculate(a, b, token))

    return stack[0]

