    def divide(a, b):
        if b == 0:
            raise ValueError("Division by zero")
        return int(a / b)

    stack = []
    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        else:
            num2 = stack.pop()
            num1 = stack.pop()
            if token == '+':
                stack.append(num1 + num2)
            elif token == '-':
                stack.append(num1 - num2)
            elif token == '*':
                stack.append(num1 * num2)
            elif token == '/':
