def solve(data):
    tokens = data["tokens"]
    stack = []

    def apply_operator(op):
        b = stack.pop()
        a = stack.pop()
        if op == '+':
            stack.append(a + b)
        elif op == '-':
            stack.append(a - b)
        elif op == '*':
            stack.append(a * b)
        elif op == '/':
            # Use floor division to truncate towards zero
            stack.append(int(a / b))

    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        else:
            apply_operator(token)

    return stack[0]

