from collections import defaultdict

def solve(data):
    n = data['n']
    edges = data['edges']
    source = data['source']

    # Initialize distance array with infinity for all nodes except source
    dist = [float('inf')] * n
    dist[source] = 0

    # Build adjacency list from edges
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to find shortest paths
    for _ in range(n - 1):
        updated = False
        for u, neighbors in graph.items():
            for v, weight in neighbors:
                if dist[u] + weight < dist[v]:
                    dist[v] = dist[u] + weight
                    updated = True
        if not updated:
            break

    # Handle negative cycles (if any)
    for u, neighbors in graph.items():
        for v, weight in neighbors:
            if dist[u] + weight < dist[v]:
                return [None] * n  # Negative cycle detected

    return dist

