    rows, cols = len(grid), len(grid[0])

    # Initialize the DP table with infinity except for the starting point
    dp = [[float('inf')] * cols for _ in range(rows)]
    dp[0][0] = 0

    # Fill the DP table
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == -1:
                continue
            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j] + grid[i][j])
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j-1] + grid[i][j])

    # Check if there is a valid path
    if dp[-1][-1] == float('inf'):
        return None

    # Reconstruct the path
    path = []
    x, y = rows - 1, cols - 1
    while (x, y) != (0, 0):
        path.append((x, y))
        if x > 0 and dp[x-1][y] <= dp[x][y]:
            x -= 1
        else:
            y -= 1
    path.append((0, 0))
    path.reverse()

    return path

