class Solution:
    def solve(self, data: dict) -> int:
        # Check for empty or minimal inputs
        if not data['grid'] or len(data['grid']) < 2 or len(data['grid'][0]) < 2:
            return None

        # Convert the grid to a list of lists for easier manipulation
        grid = [[0] * len(row) for row in data['grid']]

        # Fill the grid with the minimum cost to reach each cell
        for i in range(1, len(grid)):
            grid[i][0] += grid[i - 1][0]
        for j in range(1, len(grid[0])):
            grid[0][j] += grid[0][j - 1]

        for i in range(1, len(grid)):
            for j in range(1, len(grid[0])):
                if grid[i][j] == -1:
                    continue
                grid[i][j] += min(grid[i - 1][j], grid[i][j - 1])

        # Check if there is a valid path from top-left to bottom-right
        if grid[-1][-1] == float('inf'):
            return None

        return grid[-1][-1]

