import numpy as np

def solve(data):
    # Check if the input is empty
    if not data["grid"]:
        return None

    # Convert the grid to a NumPy array for easier manipulation
    grid = np.array(data["grid"])

    # Get the dimensions of the grid
    rows, cols = grid.shape

    # Initialize the DP table with infinity, except for the starting point
    dp_table = np.full((rows + 1, cols + 1), float('inf'))
    dp_table[0][0] = 0

    # Fill the DP table
    for i in range(1, rows + 1):
        for j in range(1, cols + 1):
            if grid[i-1][j-1] == -1:
                continue
            dp_table[i][j] = min(dp_table[i-1][j], dp_table[i][j-1]) + grid[i-1][j-1]

    # Check if there is a valid path
    if dp_table[-1][-1] == float('inf'):
        return None

    # Reconstruct the path from the DP table
    path = []
    i, j = rows - 1, cols - 1
    while i > 0 or j > 0:
        path.append((i, j))
        if i > 0 and dp_table[i][j] == dp_table[i-1][j]:
            i -= 1
        else:
            j -= 1

    # Reverse the path to get the correct order
    path.reverse()

    return {
        "cost": dp_table[-1][-1],
        "path": path
    }

