    def tarjan(graph, node, visited, stack, low_link, time):
        visited.add(node)
        stack.append(node)
        low_link[node] = time
        time += 1

        children = 0

        for neighbor in graph[node]:
            if neighbor not in visited:
                children += 1
                tarjan(graph, neighbor, visited, stack, low_link, time)

                low_link[node] = min(low_link[node], low_link[neighbor])
            elif neighbor in stack:
                low_link[node] = min(low_link[node], stack.index(neighbor))

        if low_link[node] == node and children > 0:
            component = []
            while stack and stack[-1] != node:
                component.append(stack.pop())
            component.append(node)
            result.append(component)

