    edges = data["edges"]

    # Step 1: Build the graph
    graph = defaultdict(list)
    reverse_graph = defaultdict(list)

    for u, v in edges:
        graph[u].append(v)
        reverse_graph[v].append(u)

    # Step 2: Topological sort
    def topo_sort(graph):
        visited = set()
        stack = []

        def dfs(node):
            if node in visited:
                return
            visited.add(node)
            for neighbor in graph[node]:
                dfs(neighbor)
            stack.append(node)

        for node in range(n):
            if node not in visited:
                dfs(node)

        return stack

    topological_order = topo_sort(graph)

    # Step 3: Reverse the graph
    for u in range(n):
        for v in reverse_graph[u]:
            reverse_graph[v].remove(u)
            reverse_graph[u].append(v)

    # Step 4: Detect SCCs
    def dfs_scc(node, component):
        visited.add(node)
        component.append(node)
        for neighbor in reverse_graph[node]:
            if neighbor not in visited:
                dfs_scc(neighbor, component)

    scc_count = 0
    visited = set()

    for node in reversed(topological_order):
        if node not in visited:
            component = []
            dfs_scc(node, component)
            scc_count += 1

    return scc_count

