from collections import defaultdict

def solve(data):
    n = data['n']
    edges = data['edges']

    # Create adjacency lists for directed graph
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)

    def dfs(node, visited, stack):
        visited[node] = True
        stack.append(node)
        for neighbor in adj_list[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited, stack)

    def reverse_graph():
        reversed_adj_list = defaultdict(list)
        for node in range(n):
            for neighbor in adj_list[node]:
                reversed_adj_list[neighbor].append(node)
        return reversed_adj_list

    # Perform DFS on original graph to find topological order
    visited = [False] * n
    stack = []
    for i in range(n):
        if not visited[i]:
            dfs(i, visited, stack)

    # Reverse the graph
    reversed_adj_list = reverse_graph()

    # Count strongly connected components using DFS on reversed graph
    component_count = 0
    visited = [False] * n
    while stack:
        node = stack.pop()
        if not visited[node]:
            component_count += 1
            dfs(node, visited, stack)

    return component_count

