class Solution {
    public static List<Integer> solve(Map<String, Object> data) {
        List<Integer> nums = (List<Integer>) data.get("nums");
        List<List<Object>> operations = (List<List<Object>>) data.get("operations");

        int n = nums.size();
        List<Integer> result = new ArrayList<>();

        // Initialize the prefix sums
        int[] prefixSums = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSums[i + 1] = prefixSums[i] + nums.get(i);
        }

        // Process each operation
        for (List<Object> op : operations) {
            String type = (String) op.get(0);
            int l = ((Number) op.get(1)).intValue();
            int r = ((Number) op.get(2)).intValue();
            int v = ((Number) op.get(3)).intValue();

            if (type.equals("add")) {
                // Update the value at index l with the new value v
                nums.set(l, v);

                // Update the prefix sums
                for (int i = l; i <= r; i++) {
                    prefixSums[i] += v;
                }
            } else if (type.equals("sum")) {
                // Append the inclusive range sum to the result
                result.add(prefixSums[r + 1] - prefixSums[l]);
            }
        }

        return result;
    }

    public static void main(String[] args) {
        Map<String, Object> input1 = new HashMap<>();
        input1.put("nums", Arrays.asList(1, 2, 3));
        input1.put("operations", Arrays.asList(
            Arrays.asList("sum", 0, 2),
            Arrays.asList("add", 0, 1, 4),
            Arrays.asList("sum", 1, 2)
        ));
        System.out.println(solve(input1)); // Expected output: [6, 9]

        Map<String, Object> input2 = new HashMap<>();
        input2.put("nums", Arrays.asList(0));
        input2.put("operations", Arrays.asList(
            Arrays.asList("add", 0, 0, -1),
            Arrays.asList("sum", 0, 0)
        ));
        System.out.println(solve(input2)); // Expected output: [-1]

        Map<String, Object> input3 = new HashMap<>();
        input3.put("nums", Arrays.asList(5, 5));
        input3.put("operations", Arrays.asList(Arrays.asList("sum", 1, 1)));
        System.out.println(solve(input3)); // Expected output: [5]

        Map<String, Object> input4 = new HashMap<>();
        input4.put("nums", Arrays.asList(3, -2, 10));
        input4.put("operations", Collections.emptyList());
        System.out.println(solve(input4)); // Expected output: []
    }
}

