        int[] counts = new int[13];
        for (int[] e : (List<int[]>) data.get("edges")) {
            counts[e[0]]++;
            counts[e[1]]++;
        }
        int ans = 0;
        for (int i = 0; i < 13; i++) {
            if (counts[i] > 0) {
                ans += Math.min(counts[i], counts[12 - i]);
