public final class Solution {
    public static Object solve(Map<String,Object> data) {
        int L = ((Number)data.get("left")).intValue();
        int R = ((Number)data.get("right")).intValue();
        List<int[]> edges = (List<int[]>)data.get("edges");

        // Edge cases: empty or minimal inputs, boundary values, duplicates, large inputs
        if (L == 0 && R == 0 || edges.isEmpty()) return 0;

        // Brute-force approach: try all possible left-to-right pairs
        int maxPairs = 0;
        for (int i = 0; i < L; i++) {
            for (int j = i + 1; j <= R; j++) {
                boolean validPair = true;
                for (int[] edge : edges) {
                    if (edge[0] == i && edge[1] == j) {
                        validPair = false;
                        break;
                    }
                }
                if (validPair) maxPairs++;
            }
        }

        // Efficient solution: use a set to store used edges
        Set<Integer> usedEdges = new HashSet<>();
        for (int[] edge : edges) {
            usedEdges.add(edge[0]);
            usedEdges.add(edge[1]);
        }

        // Count the number of disjoint left-to-right pairs using the set
        int count = 0;
        for (int i = 0; i < L; i++) {
            for (int j = i + 1; j <= R; j++) {
                if (!usedEdges.contains(i * 10 + j)) {
                    count++;
                    usedEdges.add(i * 10 + j);
                }
            }
        }

        return count;
    }
}

