class Solution {
    public static Object solve(Map<String,Object> data) {
        int L = ((Number) data.get("left")).intValue();
        int R = ((Number) data.get("right")).intValue();
        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");

        int[] count = new int[R + 1];
        for (List<Integer> edge : edges) {
            int u = edge.get(0);
            int v = edge.get(1);
            if (u <= v) {
                count[u]++;
                count[v + 1]--;
            } else {
                count[v]++;
                count[u + 1]--;
            }
        }

        int maxCount = 0;
        int currentCount = 0;
        for (int i = 0; i <= R; i++) {
            currentCount += count[i];
            maxCount = Math.max(maxCount, currentCount);
        }

        return maxCount;
    }
}

