        int maxCount = 0;
        for (int i = left; i <= right; i++) {
            int currentCount = 0;
            for (int j = i; j <= right; j++) {
                currentCount += map.getOrDefault(j, 0);
                if (currentCount > maxCount) {
                    maxCount = currentCount;
                }
            }
            count += maxCount;
        }

        return count;
    }
}

