    public static Object solve(Map<String,Object> data) {
        List<Integer> nums = (List<Integer>) data.get("nums");
        if (nums == null || nums.isEmpty()) {
            return 0;
        }

        Collections.sort(nums);

        int n = nums.size();
        int[][] dp = new int[n][n];

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                int maxCoins = 0;

                for (int k = i + 1; k < j; k++) {
                    int leftNeighbor = i == 0 ? 1 : nums[i - 1];
                    int rightNeighbor = j == n - 1 ? 1 : nums[j + 1];
                    int coins = leftNeighbor * nums[k] * rightNeighbor;

                    maxCoins = Math.max(maxCoins, coins + dp[i][k] + dp[k][j]);
                }

                dp[i][j] = maxCoins;
            }
        }

        return dp[0][n - 1];
    }
}

