        List<Integer> nums = (List<Integer>) data.get("nums");
        if (nums == null || nums.isEmpty()) return 0;

        int n = nums.size();
        Integer[] arr = new Integer[n + 2];
        for (int i = 0; i < n; i++) {
            arr[i + 1] = nums.get(i);
        }
        arr[0] = 1;
        arr[n + 1] = 1;

        int[][] dp = new int[n + 2][n + 2];
        for (int len = 2; len <= n + 1; len++) {
            for (int i = 1; i <= n - len + 2; i++) {
                int j = i + len - 1;
                for (int k = i; k <= j - 1; k++) {
                    dp[i][j] = Math.max(dp[i][j], dp[i][k] + dp[k + 1][j] + arr[i - 1] * arr[k] * arr[j]);
                }
            }
        }

        return dp[1][n];
    }
}

