                for (int k = i; k < j; k++) {
                    int coins = nums.get(i) * nums.get(k) * nums.get(j);
                    int left = k == i ? 0 : dp[i][k - 1];
                    int right = k == j ? 0 : dp[k + 1][j];

                    dp[i][j] = Math.max(dp[i][j], coins + left + right);
                }
            }
        }

        return dp[0][n - 1];
    }
}

