class Solution {
    public static Object solve(Map<String, Object> data) {
        List<Integer> nums = (List<Integer>) data.get("nums");
        if (nums.isEmpty()) return 0;

        int n = nums.size();
        int[][] dp = new int[n][n];

        // Fill the diagonal with 0s
        for (int i = 0; i < n; i++) {
            dp[i][i] = 0;
        }

        // Fill the dp table
        for (int len = 2; len <= n; len++) {
            for (int start = 0; start + len - 1 < n; start++) {
                int end = start + len - 1;
                for (int k = start + 1; k < end; k++) {
                    int leftNeighbor = start == 0 ? 1 : nums.get(start - 1);
                    int rightNeighbor = end == n - 1 ? 1 : nums.get(end + 1);
                    dp[start][end] = Math.max(dp[start][end], leftNeighbor * nums.get(k) * rightNeighbor + dp[start][k] + dp[k][end]);
                }
            }
        }

        return dp[0][n - 1];
    }
}

