        List<Integer> nums = (List<Integer>) data.get("nums");
        if (nums.isEmpty()) return 0;

        int n = nums.size();
        int[][] dp = new int[n][n];

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                int maxCoins = 0;

                for (int k = i; k <= j; k++) {
                    int leftNeighbor = k == 0 ? 1 : nums.get(k - 1);
                    int rightNeighbor = k == j ? 1 : nums.get(k + 1);
                    int currentCoins = leftNeighbor * nums.get(k) * rightNeighbor;

                    if (k > i) {
                        currentCoins += dp[i][k - 1];
                    }
                    if (k < j) {
                        currentCoins += dp[k + 1][j];
                    }

                    maxCoins = Math.max(maxCoins, currentCoins);
                }

                dp[i][j] = maxCoins;
            }
        }

        return dp[0][n - 1];
    }
}

