class Solution {
    public static int solve(Map<String, Object> data) {
        List<Integer> nums = (List<Integer>) data.get("nums");
        if (nums == null || nums.isEmpty()) {
            return 0;
        }

        int n = nums.size();
        Integer[] arr = nums.stream().mapToInt(Integer::intValue).toArray(Integer[]::new);

        // Helper function to compute the maximum coins for a subarray starting at i and ending at j
        int maxCoins(int i, int j) {
            if (i > j) {
                return 0;
            }

            int result = 0;
            for (int k = i + 1; k <= j - 1; k++) {
                int leftNeighbor = (k == i ? 1 : arr[k - 1]);
                int rightNeighbor = (k == j ? 1 : arr[k + 1]);
                int currentCoins = leftNeighbor * arr[k] * rightNeighbor;
                result = Math.max(result, currentCoins + maxCoins(i, k - 1) + maxCoins(k + 1, j));
            }
            return result;
        }

        return maxCoins(0, n - 1);
    }

    public static void main(String[] args) {
        Map<String, Object> data1 = new HashMap<>();
        data1.put("nums", Arrays.asList());
        System.out.println(solve(data1)); // Expected output: 0

        Map<String, Object> data2 = new HashMap<>();
        data2.put("nums", Arrays.asList(7));
        System.out.println(solve(data2)); // Expected output: 7

        Map<String, Object> data3 = new HashMap<>();
        data3.put("nums", Arrays.asList(3, 1, 5, 8));
        System.out.println(solve(data3)); // Expected output: 167

        Map<String, Object> data4 = new HashMap<>();
        data4.put("nums", Arrays.asList(0, 0, 2));
        System.out.println(solve(data4)); // Expected output: 2
    }
}

