public final class Solution {
    public static Object solve(Map<String, Object> data) {
        List<Integer> nums = (List<Integer>) data.get("nums");
        if (nums == null || nums.isEmpty()) return 0;

        int n = nums.size();
        int[][] dp = new int[n][n];

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                dp[i][j] = 0;

                for (int k = i; k < j; k++) {
                    int left = i > 0 ? dp[i-1][k] : 0;
                    int right = j < n - 1 ? dp[k+1][j] : 0;

                    int leftNeighbor = Math.min(i > 0 ? nums[i-1] : 1, nums[k]);
                    int rightNeighbor = Math.min(j < n - 1 ? nums[k+1] : 1, nums[j]);

                    dp[i][j] = Math.max(dp[i][j], left + right + leftNeighbor * nums[k] * rightNeighbor);
                }
            }
        }

        return dp[0][n-1];
    }

    public static void main(String[] args) {
        Map<String, Object> data = new HashMap<>();
        data.put("nums", Arrays.asList(3, 1, 5, 8));
        System.out.println(solve(data)); // Expected output: 167
    }
}

