        int n = nums.size();
        Integer[][] dp = new Integer[n][n];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                if (i == j) {
                    dp[i][j] = nums.get(i);
                } else {
                    int maxCoins = 0;
                    for (int k = i + 1; k < j; k++) {
