                        int currentCoins = nums.get(i) * nums.get(k) * nums.get(j);
                        maxCoins = Math.max(maxCoins, leftCoins + rightCoins + currentCoins);
                    }
                    dp[i][j] = maxCoins;
                }
            }
        }
        return dp[0][n - 1];
    }
}

