public final class Solution {
    public static Object solve(Map<String,Object> data) {
        List<String> queries = (List<String>) data.get("queries");
        List<String> words = (List<String>) data.get("words");

        Map<String, Boolean> wordToExactMatch = new HashMap<>();
        Map<String, Boolean> wordToPrefixMatch = new HashMap<>();

        // Preprocess the words to create maps for exact and prefix matching
        for (String word : words) {
            wordToExactMatch.put(word, true);
            if (!word.isEmpty()) {
                for (int i = 1; i <= word.length(); i++) {
                    String prefix = word.substring(0, i);
                    wordToPrefixMatch.put(prefix, true);
                }
            }
        }

        // Process each query and return the results
        List<Boolean> results = new ArrayList<>(queries.size());
        for (Map.Entry<String, Object> entry : queries.entrySet()) {
            String type = (String) entry.getKey();
            String word = (String) entry.getValue();

            if ("exact".equals(type)) {
                results.add(wordToExactMatch.containsKey(word));
            } else if ("prefix".equals(type)) {
                results.add(wordToPrefixMatch.containsKey(word));
            }
        }

        return results;
    }
}

