public final class Solution {
    public static Object solve(Map<String,Object> data) {
        List<Map.Entry<String,String>> words = new ArrayList<>();
        List<Map.Entry<String,String>> queries = new ArrayList<>();

        // Extract words from data
        if (data.containsKey("words")) {
            words.addAll((List<Map.Entry<String,String>>) data.get("words"));
        }

        // Extract queries from data
        if (data.containsKey("queries")) {
            queries.addAll((List<Map.Entry<String,String>>) data.get("queries"));
        }

        // Sort words by length for efficient prefix matching
        Collections.sort(words, Comparator.comparingInt(e -> e.getKey().length()));

        return queries.stream()
                .map(query -> {
                    String type = query.getValue().get("type");
                    String word = query.getValue().get("word");

                    if ("exact".equals(type)) {
                        return words.stream()
                                .anyMatch(entry -> entry.getKey().equalsIgnoreCase(word));
                    } else {
                        return words.stream()
                                .anyMatch(entry -> entry.getKey().startsWith(word));
                    }
                })
                .collect(Collectors.toList());
    }
}

