                        if (key.startsWith(word)) {
                            containsPrefix = true;
                            break;
                        }
                    }
                    results.add(containsPrefix);
                    break;
                default:
                    throw new IllegalArgumentException("Invalid query type");
            }
        }

        return results;
    }
