class Solution {
    public static List<Boolean> solve(Map<String, Object> data) {
        List<Map<String, Object>> queries = (List<Map<String, Object>>) data.get("queries");
        List<String> words = (List<String>) data.get("words");

        // Edge cases: empty lists
        if (queries.isEmpty() || words.isEmpty()) {
            return Collections.emptyList();
        }

        // Convert queries to a map for faster lookup
        Map<String, String> queryMap = new HashMap<>();
        for (Map<String, Object> query : queries) {
            String type = (String) query.get("type");
            String word = (String) query.get("word");
            queryMap.put(type + ":" + word.toLowerCase(), word);
        }

        // Initialize result list
        List<Boolean> results = new ArrayList<>(queries.size());

        // Process each query
        for (Map.Entry<String, String> entry : queryMap.entrySet()) {
            String key = entry.getKey();
            String word = entry.getValue();

            boolean isExactMatch = false;
            boolean isPrefixMatch = false;

            // Check exact match
            if (key.startsWith("exact:")) {
                isExactMatch = words.contains(word);
            }

            // Check prefix match
            if (!isExactMatch && key.startsWith("prefix:")) {
                String prefix = word.substring(0, word.length() - 1);
                isPrefixMatch = words.stream().anyMatch(w -> w.startsWith(prefix));
            }

            // Store the result
            results.add(isExactMatch || isPrefixMatch);
        }

        return results;
    }
}

