public final class Solution {
    public static Object solve(Map<String,Object> data) {
        Map<Integer,Integer> start = new HashMap<>();
        Map<Integer,Integer> end = new HashMap<>();

        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");
        int[] durations = (int[]) data.get("duration");

        if(edges.isEmpty()) return 0;

        for(List<Integer> e : edges){
            int u = e.get(0);
            int v = e.get(1);

            if(!start.containsKey(u)){
                start.put(u, v);
            }
            else{
                start.put(u, Math.min(start.get(u), v));
            }

            if(!end.containsKey(v)){
                end.put(v, u);
            }
            else{
                end.put(v, Math.max(end.get(v), u));
            }
        }

        Queue<int[]> q = new PriorityQueue<>((a,b)->b[1]-a[1]);

        for(int i=0;i<durations.length;i++){
            if(start.containsKey(i)){
                q.offer(new int[]{i,durations[i]});
            }
        }

        int ans = 0;

        while(!q.isEmpty()){
            int[] cur = q.poll();
            ans = Math.max(ans,cur[1]);

            if(end.containsKey(cur[0])){
                int prev = end.get(cur[0]);
                q.offer(new int[]{prev,ans});
            }
        }

        return ans == 0 ? 0 : ans + 1;
    }
}

