public final class Solution {
    public static Object solve(Map<String, Object> data) {
        List<Integer> durations = (List<Integer>) data.get("duration");
        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");

        if (durations.isEmpty()) return 0;

        int maxDuration = Collections.max(durations);
        boolean[] visited = new boolean[durations.size()];
        int earliestTime = 0;

        for (int i = 0; i < durations.size(); i++) {
            if (!visited[i]) {
                int currentTime = dfs(i, durations, edges, visited);
                if (currentTime > earliestTime) earliestTime = currentTime;
            }
        }

        return earliestTime == 0 ? -1 : earliestTime + maxDuration;
    }

    private static int dfs(int currentNode, List<Integer> durations, List<List<Integer>> edges, boolean[] visited) {
        if (visited[currentNode]) return 0;

        visited[currentNode] = true;

        int maxDuration = 0;
        for (List<Integer> edge : edges) {
            if (edge.get(0) == currentNode) {
                int nextTime = dfs(edge.get(1), durations, edges, visited);
                if (nextTime > maxDuration) maxDuration = nextTime;
            }
        }

        return maxDuration + durations.get(currentNode);
    }
}

