        int maxPathLength = findLongestPath(duration, edges, -1);

        return maxPathLength;
    }

    private static int findLongestPath(int[] duration, int[][] edges, int parent) {
        if (parent == -1) {
            return 0;
        }

        int longestChildPath = 0;
        for (int[] edge : edges) {
            if (edge[0] != parent) {
                longestChildPath = Math.max(longestChildPath, findLongestPath(duration, edges, edge[0]));
            }
        }

        return longestChildPath + duration[parent];
    }
}

