public final class Solution {
    public static Object solve(Map<String,Object> data) {
        Map<Integer, Integer> durations = new HashMap<>();
        List<List<Integer>> edges = new ArrayList<>();

        for (Object key : data.keySet()) {
            if ("duration".equals(key)) {
                durations.put(((Number) key).intValue(), ((Number) data.get(key)).intValue());
            } else if ("edges".equals(key)) {
                edges.addAll((List<List<Integer>>) data.get(key));
            }
        }

        if (durations.isEmpty() || edges.isEmpty()) {
            return 0;
        }

        int[] dp = new int[durations.size()];
        Arrays.fill(dp, -1);

        for (int i = 0; i < durations.size(); i++) {
            if (dp[i] == -1) {
                dfs(i, durations, edges, dp);
            }
        }

        int maxTime = 0;
        for (int time : dp) {
            maxTime = Math.max(maxTime, time);
        }

        return maxTime == -1 ? 0 : maxTime;
    }

    private static void dfs(int node, Map<Integer, Integer> durations, List<List<Integer>> edges, int[] dp) {
        if (dp[node] != -1) {
            return;
        }

        int duration = durations.get(node);
        dp[node] = duration;

        for (List<Integer> edge : edges) {
            if (edge.get(0) == node) {
                dfs(edge.get(1), durations, edges, dp);
                dp[node] += Math.max(0, dp[edge.get(1)] - duration);
            }
        }
    }
}

