    public static Object solve(Map<String, Object> data) {
        List<Integer> durations = (List<Integer>) data.get("duration");
        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");

        // Create a map to store the start times of each task
        Map<Integer, Integer> startTimes = new HashMap<>();

        // Calculate the start time for each task using topological sort
        if (!topologicalSort(durations, edges, startTimes)) {
            return 0;
        }

        // Find the maximum start time among all tasks
        int maxStartTime = Collections.max(startTimes.values());

        return maxStartTime + durations.size();
    }

    private static boolean topologicalSort(List<Integer> durations, List<List<Integer>> edges, Map<Integer, Integer> startTimes) {
        // Count the number of incoming edges for each task
        Map<Integer, Integer> inDegree = new HashMap<>();
        for (int i = 0; i < durations.size(); i++) {
            inDegree.put(i, 0);
        }
        for (List<Integer> edge : edges) {
            inDegree.put(edge.get(1), inDegree.getOrDefault(edge.get(1), 0) + 1);
        }

        // Use a queue to perform topological sorting
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < durations.size(); i++) {
            if (inDegree.get(i) == 0) {
                queue.add(i);
            }
        }

        int count = 0;
        while (!queue.isEmpty()) {
            int current = queue.poll();
            startTimes.put(current, count++);

            for (List<Integer> edge : edges) {
                if (edge.get(0) == current) {
                    inDegree.put(edge.get(1), inDegree.get(edge.get(1)) - 1);
                    if (inDegree.get(edge.get(1)) == 0) {
                        queue.add(edge.get(1));
                    }
                }
            }
