        }

        for (List<Integer> edge : edges) {
            int u = edge.get(0);
            int v = edge.get(1);
            adjList.get(u).add(v);
        }

        Queue<int[]> queue = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));
        queue.offer(new int[]{0, 0});

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int node = current[0];
            int startTime = current[1];

            for (int neighbor : adjList.get(node)) {
                if (startTime + durations.get(neighbor) < dp[neighbor]) {
                    dp[neighbor] = startTime + durations.get(neighbor);
                    queue.offer(new int[]{neighbor, dp[neighbor]});
                }
            }
        }

        return dp[n - 1] == Integer.MAX_VALUE ? 0 : dp[n - 1];
    }
}

