            return 0;
        }

        int n = durations.size();
        Map<Integer, Integer> inDegree = new HashMap<>();
        Map<Integer, Integer> maxDurationAtNode = new HashMap<>();

        // Initialize in-degree and maximum duration at each node
        for (int i = 0; i < n; i++) {
            inDegree.put(i, 0);
            maxDurationAtNode.put(i, durations.get(i));
        }

        // Build adjacency list representation of the graph
        Map<Integer, List<Integer>> adjList = new HashMap<>();
        for (List<Integer> edge : edges) {
            int u = edge.get(0);
            int v = edge.get(1);
            adjList.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
            inDegree.put(v, inDegree.getOrDefault(v, 0) + 1);
        }

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (inDegree.get(i) == 0) {
                queue.offer(i);
            }
        }

        long earliestFinishTime = 0;

        while (!queue.isEmpty()) {
            int currentNode = queue.poll();

            // Update maximum duration at each node
            for (Integer neighbor : adjList.get(currentNode)) {
                maxDurationAtNode.put(neighbor, Math.max(maxDurationAtNode.get(neighbor), maxDurationAtNode.get(currentNode) + durations.get(neighbor)));
            }

            // If current node has no more incoming edges, update earliest finish time
            if (--inDegree.get(currentNode) == 0) {
                earliestFinishTime = Math.max(earliestFinishTime, maxDurationAtNode.get(currentNode));
            }
        }

        // Check if there is a cycle
