class Solution {
    public static long solve(Map<String, Object> data) {
        List<Integer> durations = (List<Integer>) data.get("duration");
        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");

        // Edge cases: empty or minimal inputs
        if (durations == null || durations.isEmpty() || edges == null || edges.isEmpty()) {
            return 0;
        }

        int n = durations.size();
        List<Long> dp = new ArrayList<>(Collections.nCopies(n, Long.MAX_VALUE));
        Set<Integer> visited = new HashSet<>();

        // Build the topological order using Kahn's algorithm
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (!visited.contains(i)) {
                dfs(i, queue, visited, durations, edges);
            }
        }

        // Calculate the latest start time for each task
        while (!queue.isEmpty()) {
            int current = queue.poll();
            for (List<Integer> edge : edges) {
                if (edge.get(0) == current) {
                    dp[edge.get(1)] = Math.min(dp[edge.get(1)], dp[current] + durations[edge.get(0)]);
                }
            }
        }

        // Find the maximum end time among all tasks
        long maxEndTime = 0;
        for (Long time : dp) {
            maxEndTime = Math.max(maxEndTime, time);
        }

        return maxEndTime == Long.MAX_VALUE ? 0 : maxEndTime;
    }

    private void dfs(int node, Queue<Integer> queue, Set<Integer> visited, List<Integer> durations, List<List<Integer>> edges) {
        visited.add(node);
        for (List<Integer> edge : edges) {
            if (edge.get(1) == node) {
                queue.offer(edge.get(0));
            }
        }
        for (int neighbor : edges) {
            if (neighbor.get(0) == node && !visited.contains(neighbor.get(1))) {
                dfs(neighbor.get(1), queue, visited, durations, edges);
            }
        }
    }
}

