            Collections.sort(edge); // Sort each edge to ensure order
            if (!uniqueEdges.add(edge)) {
                throw new IllegalArgumentException("Duplicate edge found.");
            }
        }

        // Create a directed graph
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int i = 0; i < durations.size(); i++) {
            graph.put(i, new ArrayList<>());
        }

        // Build the graph from edges
        for (List<Integer> edge : edges) {
            graph.get(edge.get(0)).add(edge.get(1));
        }

        // Topological sort
        Queue<Integer> queue = new LinkedList<>();
        int maxTime = 0;

        // Add nodes with no incoming edges to the queue
        for (int i = 0; i < durations.size(); i++) {
            if (graph.get(i).isEmpty()) {
                queue.offer(i);
                maxTime = Math.max(maxTime, durations.get(i));
            }
        }

        // Perform topological sorting
        while (!queue.isEmpty()) {
            int current = queue.poll();
            for (Integer neighbor : graph.get(current)) {
                durations.set(neighbor, Math.max(durations.get(neighbor), durations.get(current) + durations.get(neighbor)));
                if (graph.get(neighbor).isEmpty()) {
                    queue.offer(neighbor);
                    maxTime = Math.max(maxTime, durations.get(neighbor));
                }
            }
        }

        // Check if there are any cycles
        boolean hasCycle = false;
        for (List<Integer> edge : edges) {
            if (edge.contains(queue.peek())) {
                hasCycle = true;
                break;
            }
        }

        // If there's a cycle, return -1
        if (hasCycle) {
            return -1;
        }

        return maxTime;
    }

    public static void main(String[] args) {
        System.out.println(solve(new HashMap<String, Object>() {{
            put("duration", Arrays.asList(5));
            put("edges", Arrays.asList(Arrays.asList(0, 1)));
        }})); // Expected output: 5

        System.out.println(solve(new HashMap<String, Object>() {{
            put("duration", Arrays.asList(3, 4, 5));
            put("edges", Arrays.asList(Arrays.asList(0, 1), Arrays.asList(1, 2)));
        }})); // Expected output: 12

        System.out.println(solve(new HashMap<String, Object>() {{
            put("duration", Arrays.asList(2, 5, 9));
            put("edges", Arrays.asList(Arrays.asList(0, 2), Arrays.asList(1, 2)));
        }})); // Expected output: 14

        System.out.println(solve(new HashMap<String, Object>() {{
            put("duration", Arrays.asList(5, 6, 7));
            put("edges", Arrays.asList(Arrays.asList(0, 1), Arrays.asList(1, 2), Arrays.asList(2, 3)));
        }})); // Expected output: 18

        System.out.println(solve(new HashMap<String, Object>() {{
            put("duration", Arrays.asList(1, 2, 3, 4, 5));
            put("edges", Arrays.asList(Arrays.asList(0, 1), Arrays.asList(1, 2), Arrays.asList(2, 3), Arrays.asList(3, 4)));
        }})); // Expected output: 15

        System.out.println(solve(new HashMap<String, Object>() {{
            put("duration", Arrays.asList(1, 2, 3, 4, 5));
            put("edges", Arrays.asList(Arrays.asList(0, 1), Arrays.asList(1, 2), Arrays.asList(2, 3), Arrays.asList(3, 4), Arrays.asList(4, 0)));
        }})); // Expected output: -1
    }
}

import java.util.*;

class Solution {
    public static Object solve(Map<String, Object> data) {
        int[] durations = ((List<Integer>) data.get("duration")).stream().mapToInt(Integer::intValue).toArray();
        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");

        Map<Integer, Integer> inDegree = new HashMap<>();
        Map<Integer, List<Integer>> adjList = new HashMap<>();

        for (int i = 0; i < durations.length; i++) {
            inDegree.put(i, 0);
            adjList.put(i, new ArrayList<>());
        }

        for (List<Integer> edge : edges) {
            adjList.get(edge.get(0)).add(edge.get(1));
            inDegree.put(edge.get(1), inDegree.getOrDefault(edge.get(1), 0) + 1);
        }

        Queue<Integer> queue = new LinkedList<>();
        int maxTime = 0;

        for (int i = 0; i < durations.length; i++) {
            if (inDegree.get(i) == 0) {
                queue.offer(i);
                maxTime = Math.max(maxTime, durations[i]);
            }
        }

        while (!queue.isEmpty()) {
            int current = queue.poll();
            maxTime += durations[current];

            for (int neighbor : adjList.get(current)) {
                inDegree.put(neighbor, inDegree.get(neighbor) - 1);

                if (inDegree.get(neighbor) == 0) {
                    queue.offer(neighbor);
                }
            }
        }

        return maxTime;
    }
}

import java.util.*;

class Solution {
    public static Object solve(Map<String,Object> data) {
        List<Integer> durations = (List<Integer>) data.get("duration");
        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");

        // Create an array to store the start times of each task
        int[] startTimes = new int[durations.size()];
        Arrays.fill(startTimes, Integer.MAX_VALUE);

        // Set the start time of the first task to 0
        startTimes[0] = 0;

        // Process the edges to determine the start times of other tasks
        for (List<Integer> edge : edges) {
            int u = edge.get(0);
            int v = edge.get(1);
            startTimes[v] = Math.min(startTimes[v], startTimes[u] + durations[u]);
        }

        // Find the maximum start time, which will be the latest time all tasks can finish
        int maxStartTime = Arrays.stream(startTimes).max().orElse(0);
        return maxStartTime;
    }
}

import java.util.*;

class Solution {
    public static Object solve(Map<String,Object> data) {
        int[] durations = ((List<Integer>) data.get("duration")).stream().mapToInt(Integer::intValue).toArray();
        List<int[]> edges = ((List<List<Integer>>) data.get("edges")).stream()
            .map(e -> new int[]{e.get(0), e.get(1)})
            .collect(Collectors.toList());

        if (durations.length == 0 || edges.isEmpty()) {
            return 0;
        }

        // Create an array to keep track of the end times of each task
        int[] endTimes = new int[durations.length];
        Arrays.fill(endTimes, Integer.MAX_VALUE);

        // Process each edge
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];

            // Update the end time of task u to the maximum of its current end time and the sum of its duration and the start time of task v
            endTimes[u] = Math.max(endTimes[u], durations[v] + endTimes[v]);
        }

        // Find the maximum end time among all tasks
        int maxEndTime = Arrays.stream(endTimes).max().getAsInt();

        // If any task has an end time of Integer.MAX_VALUE, it means there is no valid schedule
        if (maxEndTime == Integer.MAX_VALUE) {
            return 0;
        }

        // Otherwise, the maximum end time is the earliest time all tasks can finish
        return maxEndTime;
    }

    public static void main(String[] args) {
        System.out.println(solve(Collections.singletonMap("duration", Arrays.asList(5)), Collections.emptyList())); // Expected output: 5
        System.out.println(solve(Collections.singletonMap("duration", Arrays.asList(3, 4, 5)), Collections.emptyList())); // Expected output: 12
        System.out.println(solve(Collections.singletonMap("duration", Arrays.asList(2, 5, 9)), Collections.singletonList(new ArrayList<>(Arrays.asList(0, 2))));// Expected output: 14
        System.out.println(solve(Collections.singletonMap("duration", Arrays.asList(5, 7, 8, 10)), Collections.singletonList(new ArrayList<>(Arrays.asList(0, 1), new ArrayList<>(Arrays.asList(1, 2), new ArrayList<>(Arrays.asList(2, 3)))); // Expected output: 22
    }
}

import java.util.*;

class Solution {
    public static long solve(Map<String, Object> data) {
        List<Integer> durations = (List<Integer>) data.get("duration");
        List<int[]> edges = (List<int[]>) data.get("edges");

        // Edge cases: empty or minimal inputs
        if (durations == null || durations.isEmpty() || edges == null || edges.isEmpty()) {
            return 0;
        }

        int n = durations.size();
        Map<Integer, Integer> startTimes = new HashMap<>();
        Map<Integer, Integer> endTimes = new HashMap<>();

        // Build the graph and calculate start and end times
        for (int i = 0; i < n; i++) {
            startTimes.put(i, 0);
            endTimes.put(i, 0);
        }

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];

            // If u finishes before v starts, update the start time of v
            if (startTimes.get(u) > endTimes.get(v)) {
                startTimes.put(v, startTimes.get(u));
            }

            // Update the end time of u
            endTimes.put(u, endTimes.get(u) + durations.get(u));
        }

        // Find the maximum end time which is the earliest time all tasks can finish
        long maxEndTime = 0;
        for (int endTime : endTimes.values()) {
            maxEndTime = Math.max(maxEndTime, endTime);
        }

        return maxEndTime;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(solve(Map.of("duration", Arrays.asList(5), "edges", Collections.emptyList()))); // Expected: 0
        System.out.println(solve(Map.of("duration", Arrays.asList(5), "edges", Collections.singletonList(new int[]{0, 1}))));// Expected: 5
        System.out.println(solve(Map.of("duration", Arrays.asList(3, 4, 5), "edges", Arrays.asList(new int[]{0, 1}, new int[]{1, 2}))));// Expected: 12
        System.out.println(solve(Map.of("duration", Arrays.asList(2, 5, 9), "edges", Arrays.asList(new int[]{0, 2}, new int[]{1, 2}))));// Expected: 14
    }
}
